command:
if [[ -L lib || -L test || -L lib/{module}.pl || ( -e lib/{module}.pl && ! -f lib/{module}.pl ) ]]; then printf 'scaffold: ruta de Perl no segura / unsafe Perl path
' >&2; false; else mkdir -p lib test && { test -e lib/{module}.pl || (set -C; printf 'package {Module};

use strict;
use warnings;

1;
' > lib/{module}.pl); }; fi

if [[ -f Tests/{module}Tests/{module}Tests.swift ]]; then sample="$(sed 's/@MODULE@/{module}/g' {root}/scripts/data/scaffold_templates/swift.Test.swift)" && test -n "$sample" && { cmp -s Tests/{module}Tests/{module}Tests.swift <(printf '%s
' "$sample"); result=$?; if [[ "$result" == 0 ]]; then printf 'import Testing
@testable import {module}
' > Tests/{module}Tests/{module}Tests.swift; elif [[ "$result" != 1 ]]; then printf 'scaffold: no se pudo comparar la muestra Swift / could not compare Swift sample
' >&2; false; fi; }; fi
